contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 seedDrugs, uint256 extraSeedDrugs) public payable {
        require(seedDrugs > 0 && extraSeedDrugs > 0);
        // capture initial observable state
        bool initBefore = c.initialized();
        uint256 marketBefore = c.marketDrugs();
        // call seedMarket once with seedDrugs (payable allowed but not required)
        // ensure this contract has enough balance to send zero value (no need to send Ether)
        c.seedMarket{value: 0}(seedDrugs);
        // read state after first seeding
        bool initAfter = c.initialized();
        uint256 marketAfter = c.marketDrugs();

        // attempt a second seedMarket call with a different nonzero amount and catch revert
        bool revertedSecond;
        try c.seedMarket{value: 0}(extraSeedDrugs) {
            revertedSecond = false;
        } catch {
            revertedSecond = true;
        }

        // The invariant to prove: if initially marketDrugs was zero and initialized false,
        // then after a single successful seedMarket(seedDrugs>0) the contract becomes initialized
        // and marketDrugs equals the provided seedDrugs, and any subsequent seedMarket call reverts.
        assert(
            (marketBefore == 0 && initBefore == false)
            ? (initAfter == true && marketAfter == seedDrugs && revertedSecond == true)
            : true
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that performs the property test
    function run(uint256 seedDrugs) public payable {
        // require a valid positive seed to initialize market (seedMarket requires marketDrugs==0)
        require(seedDrugs > 0);

        // ensure this test contract has enough balance if seedMarket expects payable (it doesn't require value but allow 0)
        // seed the market to set initialized = true
        c.seedMarket{value: 0}(seedDrugs);

        // precondition: this contract currently has Kilos == 0 (getFreeKilo requires that)
        // verify by reading the public getter
        uint256 kilosBefore = c.getMyKilo();
        // Ensure the precondition holds; if not, we cannot call getFreeKilo per contract rules
        require(kilosBefore == 0);

        // call getFreeKilo which should set Kilos[msg.sender] to STARTING_KILOS and lastCollect to block.timestamp
        c.getFreeKilo();

        // read observable values after the call
        uint256 kilosAfter = c.getMyKilo();
        uint256 starting = c.STARTING_KILOS();
        uint256 last = c.lastCollect(address(this));

        // General rule: after a valid getFreeKilo call when initialized and caller had 0 kilos,
        // the caller's Kilos equals STARTING_KILOS and lastCollect becomes nonzero (timestamp set).
        assert(kilosAfter == starting && last != 0);
    }

    // allow receiving ether if needed by the environment
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that performs the property test
    // amount is arbitrary uint256 input to check the devFee behavior
    function run(uint256 amount) public payable {
        // no precondition on amount

        // call the view function devFee to observe the reported fee
        uint256 fee = c.devFee(amount);

        // compute expected value using only safe arithmetic that matches Solidity truncating division
        // expected = (amount * 4) / 100
        uint256 expected = (amount * 4) / 100;

        // general property: devFee must equal floor(amount * 4 / 100)
        assert(fee == expected);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that performs the property test
    // amount: ETH to send to buyDrugs; seedAmount: initial marketDrugs to seed the market
    function run(uint256 seedAmount, uint256 amount) public payable {
        require(seedAmount > 0, "seed must be positive");
        // Must have enough balance to send `amount` when calling buyDrugs
        require(address(this).balance >= amount, "insufficient test contract balance");
        // initialize market so buy/sell/collect functions are allowed
        // seedMarket is payable; supply some wei as part of seeding (use 0 value here allowed)
        c.seedMarket{value: 0}(seedAmount);

        // ensure caller (this contract) has zero kilos so its first buy increases claimedDrugs monotonically
        // get current claimedDrugs
        uint256 before = c.claimedDrugs(address(this));

        // perform buyDrugs sending `amount` wei
        bool reverted;
        try c.buyDrugs{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-value
        uint256 after = c.claimedDrugs(address(this));

        // If the call reverted, claimedDrugs must be unchanged. If it succeeded, claimedDrugs must be >= before.
        assert(reverted ? (after == before) : (after >= before));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that performs the property test
    // seedAmount: initial marketDrugs to seed the market (must be >0)
    // amount: ETH to send to buyDrugs; this contract must hold at least `amount` wei
    function run(uint256 seedAmount, uint256 amount) public payable {
        require(seedAmount > 0, "seed must be positive");
        require(address(this).balance >= amount, "insufficient test contract balance");

        // seed the market so buyDrugs is allowed
        c.seedMarket{value: 0}(seedAmount);

        // read claimedDrugs before the call
        uint256 beforeClaimed = c.claimedDrugs(address(this));

        // attempt to call buyDrugs sending `amount` wei
        bool reverted;
        try c.buyDrugs{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read claimedDrugs after the call
        uint256 afterClaimed = c.claimedDrugs(address(this));

        // If reverted, value must be unchanged; otherwise it must be >= previous value
        assert(reverted ? (afterClaimed == beforeClaimed) : (afterClaimed >= beforeClaimed));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test the behavior of collectDrugs(address ref)
    // params: ref address to set as referral, and padSeconds to advance time via lastCollect emulation by calling getFreeKilo then waiting
    function run(address ref) public payable {
        // initialize market (seedMarket) so collectDrugs and other funcs don't revert.
        // seedMarket requires marketDrugs==0; this is true for fresh c deployed by checker.
        c.seedMarket(1000);

        // Ensure the caller has some kilos: call getFreeKilo which sets STARTING_KILOS for msg.sender
        c.getFreeKilo();

        // Observe before-values
        uint256 beforeKilos = c.getMyKilo();
        uint256 beforeClaimed = c.claimedDrugs(address(this));
        uint256 beforeMarket = c.marketDrugs();
        uint256 DRUGS_TO_PRODUCE_1KILO = c.DRUGS_TO_PRODUCE_1KILO();

        // compute available drugs prior to collect: getMyDrugs = claimedDrugs + getDrugsSinceLastCollect
        uint256 beforeMyDrugs = c.getMyDrugs();

        // perform the call and capture whether it reverted
        bool reverted;
        try c.collectDrugs(ref) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After-values (only valid if call did not revert; still readable if reverted)
        uint256 afterKilos = c.getMyKilo();
        uint256 afterClaimed = c.claimedDrugs(address(this));
        uint256 afterMarket = c.marketDrugs();

        // If collectDrugs reverted then no state change is required; assert that it reverted only when initialized==false.
        // Otherwise, the increase in Kilos equals floor(beforeMyDrugs / DRUGS_TO_PRODUCE_1KILO), claimedDrugs reset to 0 for caller,
        // and marketDrugs increased by at least floor(beforeMyDrugs/10).

        // read initialized to distinguish expected revert reason
        bool initialized = c.initialized();

        assert(
            // If reverted: it must be because contract wasn't initialized (collectDrugs has only require(initialized))
            (reverted && !initialized)
            ||
            // Otherwise: Kilos increased by floor(beforeMyDrugs / DRUGS_TO_PRODUCE_1KILO)
            (!reverted && afterKilos == beforeKilos + (beforeMyDrugs / DRUGS_TO_PRODUCE_1KILO)
                // caller's claimedDrugs should be set to 0
                && afterClaimed == 0
                // marketDrugs increased by at least floor(beforeMyDrugs/10)
                && afterMarket >= beforeMarket + (beforeMyDrugs / 10)
            )
        );
    }

    // receive not needed but allow Ether intake if ever required
    receive() external payable {}
}
